package com.logatron.processor.observability;
import io.micrometer.core.instrument.*;import org.springframework.stereotype.Component;import java.util.concurrent.TimeUnit;
@Component("logatronProcessorMetrics") public class ProcessorMetrics {public final Counter received,parsed,normalized,masked,rejected,dlq,duplicates,stored,clickHouseFailures;public final DistributionSummary batchSize;public final Timer insertDuration;public ProcessorMetrics(MeterRegistry r){received=r.counter("logatron.processor.received");parsed=r.counter("logatron.processor.parsed");normalized=r.counter("logatron.processor.normalized");masked=r.counter("logatron.processor.masked");rejected=r.counter("logatron.processor.rejected");dlq=r.counter("logatron.processor.dlq");duplicates=r.counter("logatron.processor.duplicates");stored=r.counter("logatron.processor.stored");clickHouseFailures=r.counter("logatron.processor.clickhouse.failures");batchSize=DistributionSummary.builder("logatron.processor.batch.size").register(r);insertDuration=Timer.builder("logatron.processor.clickhouse.insert.duration").register(r);} }